import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.TreeMap;

/** Seeded regression check of the core simulation (breeding/aging). */
public class Harness
{
    private static String runOnce(int steps)
    {
        Randomizer.reset();
        Random rand = Randomizer.getRandom();
        Field field = new Field(40, 40);
        List<Actor> actors = new ArrayList<>();
        for (int row = 0; row < field.getDepth(); row++) {
            for (int col = 0; col < field.getWidth(); col++) {
                Location loc = new Location(row, col);
                double r = rand.nextDouble();
                if (r <= 0.02)      actors.add(new Lion(true, field, loc));
                else if (r <= 0.04) actors.add(new Hyena(true, field, loc));
                else if (r <= 0.06) actors.add(new Gazelle(true, field, loc));
                else if (r <= 0.08) actors.add(new Mouse(true, field, loc));
                else if (r <= 0.10) actors.add(new FennecFox(true, field, loc));
                else if (r <= 0.30) actors.add(new Grass(true, field, loc));
            }
        }
        for (int step = 0; step < steps; step++) {
            List<Actor> newborns = new ArrayList<>();
            List<Actor> next = new ArrayList<>();
            for (Actor a : actors) {
                if (!((Organism) a).isExpired()) a.act(newborns);
                if (!((Organism) a).isExpired()) next.add(a);
            }
            next.addAll(newborns);
            actors = next;
        }
        TreeMap<String, Integer> counts = new TreeMap<>();
        for (Actor a : actors) counts.merge(a.getClass().getSimpleName(), 1, Integer::sum);
        return counts.toString();
    }

    public static void main(String[] args)
    {
        for (int steps : new int[]{0, 2, 5, 10}) {
            System.out.println("steps=" + steps + "  " + runOnce(steps));
        }
    }
}

